/** Detection's scan and its one retry, over a stubbed runAgent. */
import {
  AgenticDetectionTimeoutError,
  detectProjectsWithAgent,
} from '@programs/detection/agentic';
import { DEFAULT_BINDING, runAgent, RunOutcome } from '@agent';
import { buildSession } from '@programs/session/wizard-session';
import { analytics } from '@utils/analytics';
import { ErrorCodes, type ErrorCode } from '@shared/errors';
import { HostResolution } from '@shared/host-resolution';
import { Harness } from '@shared/constants';
import { snapshot } from './helpers/run-snapshot.no-jest';

vi.mock('@utils/analytics');
vi.mock('@agent', async (importOriginal) => ({
  ...(await importOriginal<typeof import('@agent')>()),
  runAgent: vi.fn(),
}));

const execute = vi.mocked(runAgent);
const options = {
  programId: 'posthog-integration',
  targets: [{ id: 'nextjs', name: 'Next.js' }],
};
const verdict =
  '{"path":".","framework":"Next.js","targetId":"nextjs","hasPostHog":false}';

function session() {
  const value = buildSession({ installDir: '/repo', harness: Harness.pi });
  value.credentials = {
    accessToken: 'token',
    projectApiKey: 'key',
    host: HostResolution.fromApiHost('https://us.posthog.com'),
    projectId: 1,
  };
  return value;
}

/** The run succeeds with `text` as its collected transcript. */
function emitResult(text: string) {
  return execute.mockImplementationOnce(() =>
    Promise.resolve({
      outcome: RunOutcome.Success,
      snapshot: snapshot(text),
    }),
  );
}

/** The run ends on its own deadline. */
function timeOut() {
  return execute.mockResolvedValueOnce({
    outcome: RunOutcome.Failed,
    failure: {
      code: ErrorCodes.AgenticDetectionTimeout,
      message: 'Project scan timed out',
    },
    snapshot: snapshot(''),
  });
}

/** The run fails with `code`, and `error` when it has one. */
function fail(code: ErrorCode, error?: Error) {
  return execute.mockResolvedValueOnce({
    outcome: RunOutcome.Failed,
    failure: { code, message: error?.message ?? code, ...(error && { error }) },
    snapshot: snapshot(''),
  });
}

/** The run succeeds with a typed report. */
function succeedWith(structuredOutput: unknown) {
  return execute.mockResolvedValueOnce({
    outcome: RunOutcome.Success,
    structuredOutput,
    snapshot: snapshot(''),
  });
}

describe('agentic detection retry', () => {
  beforeEach(() => {
    vi.resetAllMocks();
    vi.mocked(analytics.getAllFlagsForWizard).mockResolvedValue({});
    vi.mocked(analytics.getWizardFlagPayloads).mockReturnValue({});
  });

  afterEach(() => vi.restoreAllMocks());

  it('runs both attempts through runAgent, read-only, with a schema and deadline, its own prompt, no remark and a deferred scan report', async () => {
    vi.mocked(analytics.getAllFlagsForWizard).mockResolvedValue({
      'a-flag': 'variant',
    });
    vi.mocked(analytics.getWizardFlagPayloads).mockReturnValue({
      'a-flag': { route: 'pi' },
    });
    timeOut();
    emitResult(verdict);

    await detectProjectsWithAgent(session(), options);

    const calls = execute.mock.calls;
    expect(calls).toHaveLength(2);
    // The launch's harness applies to the first attempt and the retry runs the
    // SDK; the scan keeps out of the run's routing analytics.
    expect(calls.map(([config]) => config.routing)).toEqual(
      (['first', 'retry'] as const).map((scan) => ({
        binding: DEFAULT_BINDING,
        overrides: { harness: Harness.pi },
        record: false,
        scan,
      })),
    );
    expect(calls.map(([config]) => config.run.structured?.timeoutMs)).toEqual([
      60_000, 90_000,
    ]);
    for (const [config] of calls) {
      expect(config.wizardFlags).toEqual({ 'a-flag': 'variant' });
      expect(config.wizardFlagPayloads).toEqual({ 'a-flag': { route: 'pi' } });
      expect(config.run.structured?.schema).toMatchObject({
        required: ['repoType', 'projects'],
      });
      expect(config.run.readOnly).toBe(true);
      // The program run's report counts the scan's scans.
      expect(config.scanReport).toBe('defer');
      expect(config.run).toMatchObject({
        collectTranscript: true,
        requestRemark: false,
      });
      // The run definition's prompt replaces the assembled program prompt.
      expect(config.run.prompt?.({} as never)).toContain(
        'You are scanning a code repository',
      );
    }
  });

  it('uses the typed result when the model emits a pretty-printed final report', async () => {
    const report = {
      repoType: 'single',
      projects: [
        {
          path: '.',
          framework: 'Next.js',
          matchingTargets: ['nextjs'],
          targetId: 'nextjs',
          hasPostHog: false,
          evidence: 'next in dependencies',
        },
      ],
    };
    execute.mockResolvedValueOnce({
      outcome: RunOutcome.Success,
      structuredOutput: report,
      snapshot: snapshot(JSON.stringify(report, null, 2)),
    });

    expect(
      (await detectProjectsWithAgent(session(), options)).projects[0].targetId,
    ).toBe('nextjs');
    expect(execute).toHaveBeenCalledTimes(1);
  });

  it('retries invalid structured output once but propagates ordinary API failures', async () => {
    fail(ErrorCodes.AgentInvalidStructuredOutput);
    emitResult(verdict);
    expect(
      (await detectProjectsWithAgent(session(), options)).projects[0].targetId,
    ).toBe('nextjs');
    const failure = new Error('API unavailable');
    fail(ErrorCodes.AgentApiError, failure);
    await expect(detectProjectsWithAgent(session(), options)).rejects.toThrow(
      failure,
    );
    expect(execute).toHaveBeenCalledTimes(3);
  });

  it('retries a typed report that misses the schema rather than coercing it', async () => {
    const project = {
      path: '.',
      framework: 'Next.js',
      matchingTargets: ['nextjs'],
      targetId: 'nextjs',
      evidence: 'next in dependencies',
    };
    succeedWith({
      repoType: 'single',
      projects: [{ ...project, hasPostHog: 'yes' }],
    });
    succeedWith({
      repoType: 'single',
      projects: [{ ...project, hasPostHog: true }],
    });

    const report = await detectProjectsWithAgent(session(), options);

    expect(report.projects[0].hasPostHog).toBe(true);
    expect(execute).toHaveBeenCalledTimes(2);
  });

  it('requires and returns the pick when asked to recommend', async () => {
    const project = {
      path: '.',
      framework: 'Next.js',
      matchingTargets: ['nextjs'],
      targetId: 'nextjs',
      hasPostHog: false,
      evidence: 'next in dependencies',
      recommended: true,
    };
    succeedWith({ repoType: 'single', projects: [project] });

    const report = await detectProjectsWithAgent(session(), {
      ...options,
      recommend: true,
    });

    expect(report.projects[0].recommended).toBe(true);
    expect(execute.mock.calls[0][0].run.structured?.schema).toMatchObject({
      properties: {
        projects: {
          items: { required: expect.arrayContaining(['recommended']) },
        },
      },
    });
  });

  it('accepts an empty report without retrying, typed or recovered', async () => {
    succeedWith({ repoType: 'single', projects: [] });
    emitResult('{"repoType":"single","projects":[]}');
    for (let run = 0; run < 2; run++) {
      await expect(
        detectProjectsWithAgent(session(), options),
      ).resolves.toEqual({ repoType: 'single', projects: [] });
    }
    expect(execute).toHaveBeenCalledTimes(2);
  });

  it('restarts the scan once when the first result has no JSON', async () => {
    emitResult('I found a Next.js project.');
    emitResult(verdict);

    const report = await detectProjectsWithAgent(session(), options);

    expect(report.projects).toEqual([
      {
        path: '.',
        framework: 'Next.js',
        targetId: 'nextjs',
        hasPostHog: false,
      },
    ]);
    expect(execute).toHaveBeenCalledTimes(2);
    expect(execute.mock.calls.map(([config]) => config.routing.scan)).toEqual([
      'first',
      'retry',
    ]);
  });

  it('returns the first valid report without starting a retry', async () => {
    emitResult(verdict);

    const report = await detectProjectsWithAgent(session(), options);

    expect(report.projects).toHaveLength(1);
    expect(execute).toHaveBeenCalledTimes(1);
  });

  it('retries a timed-out first run on the SDK', async () => {
    const events: string[] = [];
    timeOut();
    emitResult(verdict);

    const report = await detectProjectsWithAgent(session(), {
      ...options,
      onEvent: (line) => events.push(line),
    });

    expect(report.projects).toHaveLength(1);
    expect(events).toContain('Project scan timed out; retrying...');
    expect(execute.mock.calls.map(([config]) => config.routing.scan)).toEqual([
      'first',
      'retry',
    ]);
  });

  it('reports a typed timeout when the retry also times out', async () => {
    timeOut();
    timeOut();

    const scan = detectProjectsWithAgent(session(), options);

    await expect(scan).rejects.toThrow(AgenticDetectionTimeoutError);
    await expect(scan).rejects.toThrow(
      'Project scan attempt 2 timed out after 90s',
    );
    expect(execute).toHaveBeenCalledTimes(2);
  });

  it('accepts a streamed verdict after a no-JSON result', async () => {
    const events: string[] = [];
    emitResult('Found a project, but no JSON report.');
    // The transcript holds the streamed text before the final message.
    emitResult(`${verdict}\nDone.`);

    const report = await detectProjectsWithAgent(session(), {
      ...options,
      onEvent: (line) => events.push(line),
    });

    expect(report.projects).toEqual([
      {
        path: '.',
        framework: 'Next.js',
        targetId: 'nextjs',
        hasPostHog: false,
      },
    ]);
    expect(events).toContain('Retrying project scan...');
    expect(execute).toHaveBeenCalledTimes(2);
    expect(execute.mock.calls[0][1]).toBe(execute.mock.calls[1][1]);
  });

  it('stops after one retry if neither result has JSON', async () => {
    emitResult('No JSON here.');
    emitResult('Still no JSON.');

    await expect(detectProjectsWithAgent(session(), options)).rejects.toThrow(
      'Agent did not return a JSON object after retry',
    );
    expect(execute).toHaveBeenCalledTimes(2);
  });
});

name: Wizard CI Trigger

on:
  pull_request:
    types: [opened]
  issue_comment:
    types: [created]
  workflow_dispatch:
    inputs:
      pr_number:
        description: 'Pull request number to post the hint comment on'
        required: true
        type: number

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  # ============================================================================
  # POST WELCOME: First-time hint with all available apps
  # ============================================================================
  post-welcome:
    if: github.event_name == 'pull_request' || github.event_name == 'workflow_dispatch'
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - name: Fetch available apps from wizard-workbench
        id: fetch-apps
        run: |
          # Fetch app categories from wizard-workbench repo
          CATEGORIES=$(curl -s "https://api.github.com/repos/PostHog/wizard-workbench/contents/apps" \
            -H "Accept: application/vnd.github.v3+json" \
            | jq -r '[.[] | select(.type == "dir") | .name] | sort | .[]')

          # Only advertise directories whose workflow is CI-capable (apps/manifest.json).
          # Left empty on fetch failure, in which case no filtering is applied.
          CI_CAPABLE=$(curl -s "https://api.github.com/repos/PostHog/wizard-workbench/contents/apps/manifest.json" \
            -H "Accept: application/vnd.github.raw" \
            | jq -r '[.workflows[] | select(.ciCapable == true) | .dir] | .[]' 2>/dev/null || echo "")

          # Build lists by category
          CATEGORY_LIST=""
          APP_LIST_VISIBLE=""
          APP_LIST_COLLAPSED=""
          APP_COUNT=0
          VISIBLE_COUNT=3

          for category in $CATEGORIES; do
            # Skip directories the manifest marks as not CI-capable.
            if [ -n "$CI_CAPABLE" ] && ! echo "$CI_CAPABLE" | grep -qxF "$category"; then
              continue
            fi

            # Fetch apps in this category
            APPS=$(curl -s "https://api.github.com/repos/PostHog/wizard-workbench/contents/apps/$category" \
              -H "Accept: application/vnd.github.v3+json" \
              | jq -r '[.[] | select(.type == "dir") | .name] | sort | .[]' 2>/dev/null || echo "")

            if [ -n "$APPS" ]; then
              # Add to category list
              CATEGORY_LIST="$CATEGORY_LIST- \`/wizard-ci $category\`\n"

              # Add apps to visible or collapsed list
              for app in $APPS; do
                if [ $APP_COUNT -lt $VISIBLE_COUNT ]; then
                  APP_LIST_VISIBLE="$APP_LIST_VISIBLE- \`/wizard-ci $category/$app\`\n"
                else
                  APP_LIST_COLLAPSED="$APP_LIST_COLLAPSED- \`/wizard-ci $category/$app\`\n"
                fi
                APP_COUNT=$((APP_COUNT + 1))
              done
            fi
          done

          # Use heredoc for multiline outputs
          {
            echo "categories<<EOF"
            echo -e "$CATEGORY_LIST"
            echo "EOF"
          } >> $GITHUB_OUTPUT

          {
            echo "apps_visible<<EOF"
            echo -e "$APP_LIST_VISIBLE"
            echo "EOF"
          } >> $GITHUB_OUTPUT

          {
            echo "apps_collapsed<<EOF"
            echo -e "$APP_LIST_COLLAPSED"
            echo "EOF"
          } >> $GITHUB_OUTPUT

      - name: Post wizard-ci hint
        uses: actions/github-script@f28e40c7f34bde8b3046d885e986cb6290c5673b # v7.1.0
        env:
          CATEGORIES_OUTPUT: ${{ steps.fetch-apps.outputs.categories }}
          APPS_VISIBLE_OUTPUT: ${{ steps.fetch-apps.outputs.apps_visible }}
          APPS_COLLAPSED_OUTPUT: ${{ steps.fetch-apps.outputs.apps_collapsed }}
          PR_NUMBER: ${{ inputs.pr_number }}
        with:
          script: |
            const categories = process.env.CATEGORIES_OUTPUT || '';
            const appsVisible = process.env.APPS_VISIBLE_OUTPUT || '';
            const appsCollapsed = process.env.APPS_COLLAPSED_OUTPUT || '';
            const inputPrNumber = process.env.PR_NUMBER;

            const bodyParts = [
              '## 🧙 Wizard CI',
              '',
              'Run the Wizard CI and test your changes against [wizard-workbench](https://github.com/PostHog/wizard-workbench) example apps by replying with a GitHub comment using one of the following commands:',
              '',
              '**Test all apps:**',
              '- `/wizard-ci all`',
              '',
              '**Test all apps in a directory:**',
              categories.trim(),
              '',
              '**Test an individual app:**',
              appsVisible.trim()
            ];

            if (appsCollapsed.trim()) {
              bodyParts.push('');
              bodyParts.push('<details>');
              bodyParts.push('<summary>Show more apps</summary>');
              bodyParts.push('');
              bodyParts.push(appsCollapsed.trim());
              bodyParts.push('</details>');
            }

            bodyParts.push('');
            bodyParts.push('**Test against a Context Mill branch:**');
            bodyParts.push('- `/wizard-ci all context-mill:my-branch`');
            bodyParts.push('');
            bodyParts.push('Add `context-mill:<branch>` to any command above to pin the Context Mill branch. It defaults to `main`.');
            bodyParts.push('');
            bodyParts.push('Results will be posted here when complete.');

            const body = bodyParts.join('\n');

            const prNumber = context.eventName === 'workflow_dispatch'
              ? parseInt(inputPrNumber, 10)
              : context.payload.pull_request.number;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body
            });

  # ============================================================================
  # HANDLE COMMAND: Parse /wizard-ci and trigger workflow
  # ============================================================================
  handle-command:
    if: |
      github.event_name == 'issue_comment' &&
      github.event.issue.pull_request &&
      contains(fromJSON('["OWNER", "MEMBER", "COLLABORATOR"]'), github.event.comment.author_association) &&
      startsWith(github.event.comment.body, '/wizard-ci') &&
      !startsWith(github.event.comment.body, '/wizard-ci-snapshots')
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - name: Generate GitHub App token
        id: app-token
        uses: actions/create-github-app-token@d72941d797fd3113feb6b93fd0dec494b13a2547 # v1.12.0
        with:
          app-id: ${{ secrets.GH_APP_POSTHOG_WIZARD_CI_BOT_APP_ID }}
          private-key: ${{ secrets.GH_APP_POSTHOG_WIZARD_CI_BOT_PRIVATE_KEY }}
          owner: PostHog
          repositories: wizard-workbench,wizard

      - name: Parse command and trigger
        uses: actions/github-script@f28e40c7f34bde8b3046d885e986cb6290c5673b # v7.1.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            // Get PR details first to check state
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.issue.number
            });

            // Only allow triggers on open PRs (including drafts)
            if (pr.data.state !== 'open') {
              console.log(`PR is ${pr.data.state}, skipping trigger`);
              return;
            }

            const comment = context.payload.comment.body;
            const match = comment.match(/\/wizard-ci\s+(\S+)/);
            const firstArg = match ? match[1] : 'all';

            // A reviewer can pin the companion repo with `context-mill:<ref>`.
            // A lone pin is not an app name, so fall back to every app.
            const app = firstArg.startsWith('context-mill:') ? 'all' : firstArg;

            // The ref arrives in a PR comment, so treat it as untrusted. Accept
            // git ref characters only. Reject traversal, a leading dash and a
            // trailing slash.
            const isPlausibleRef = (ref) =>
              ref.length <= 200 &&
              /^[A-Za-z0-9._\/-]+$/.test(ref) &&
              !ref.includes('..') &&
              !ref.startsWith('-') &&
              !ref.startsWith('/') &&
              !ref.endsWith('/');

            // Read the pin from the command line only, not from later prose.
            const companion = comment
              .split(/\r?\n/)[0]
              .match(/(?:^|\s)context-mill:(\S+)/);
            const contextMillRef = companion ? companion[1] : null;

            if (contextMillRef && !isPlausibleRef(contextMillRef)) {
              core.setFailed(
                'The context-mill ref is not a valid git ref. ' +
                  'Use `/wizard-ci <app> context-mill:<branch>`.'
              );
              return;
            }

            // React with rocket to show we're processing
            await github.rest.reactions.createForIssueComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              comment_id: context.payload.comment.id,
              content: 'rocket'
            });

            // Trigger wizard-ci on wizard-workbench
            await github.rest.repos.createDispatchEvent({
              owner: 'PostHog',
              repo: 'wizard-workbench',
              event_type: 'wizard-ci-trigger',
              client_payload: {
                app: app,
                source: 'wizard-pr',
                source_repo: 'wizard',
                source_pr_number: context.payload.issue.number,
                source_pr_url: pr.data.html_url,
                wizard_ref: pr.data.head.ref,
                // Omit the key when unpinned. The workbench then uses `main`.
                ...(contextMillRef ? { context_mill_ref: contextMillRef } : {}),
                notify_slack: 'false',
                notify_pr: 'true'
              }
            });

            const pinNote = contextMillRef ? ` (context-mill ref ${contextMillRef})` : '';
            console.log(`Triggered wizard-ci for app: ${app}${pinNote}`);

  # ============================================================================
  # HANDLE SNAPSHOTS: Parse /wizard-ci-snapshots and trigger the snapshots workflow
  # ============================================================================
  # Same write-access restriction as handle-command above. This job matters more:
  # its positional `[ref]` argument is attacker-chosen, not the PR's own branch.
  handle-snapshots-command:
    if: |
      github.event_name == 'issue_comment' &&
      github.event.issue.pull_request &&
      contains(fromJSON('["OWNER", "MEMBER", "COLLABORATOR"]'), github.event.comment.author_association) &&
      startsWith(github.event.comment.body, '/wizard-ci-snapshots')
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - name: Generate GitHub App token
        id: app-token
        uses: actions/create-github-app-token@d72941d797fd3113feb6b93fd0dec494b13a2547 # v1.12.0
        with:
          app-id: ${{ secrets.GH_APP_POSTHOG_WIZARD_CI_BOT_APP_ID }}
          private-key: ${{ secrets.GH_APP_POSTHOG_WIZARD_CI_BOT_PRIVATE_KEY }}
          owner: PostHog
          repositories: wizard-workbench,wizard

      - name: Parse command and trigger snapshots
        uses: actions/github-script@f28e40c7f34bde8b3046d885e986cb6290c5673b # v7.1.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            // Only trigger on open PRs (including drafts).
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.issue.number
            });
            if (pr.data.state !== 'open') {
              console.log(`PR is ${pr.data.state}, skipping trigger`);
              return;
            }

            const body = context.payload.comment.body;

            // The ref arrives in a PR comment, so treat it as untrusted. Accept
            // git ref characters only. Reject traversal, a leading dash and a
            // trailing slash.
            const isPlausibleRef = (ref) =>
              ref.length <= 200 &&
              /^[A-Za-z0-9._\/-]+$/.test(ref) &&
              !ref.includes('..') &&
              !ref.startsWith('-') &&
              !ref.startsWith('/') &&
              !ref.endsWith('/');

            // Optional companion pin. Read it from the command line only.
            const companionToken = [REDACTED];
            const companion = body.split(/\r?\n/)[0].match(companionToken);
            const contextMillRef = companion ? companion[1] : null;

            if (contextMillRef && !isPlausibleRef(contextMillRef)) {
              core.setFailed(
                'The context-mill ref is not a valid git ref. Use ' +
                  '`/wizard-ci-snapshots <app> context-mill:<branch>`.'
              );
              return;
            }

            // Remove the pin so the positional ref cannot capture it.
            const args = contextMillRef ? body.replace(companionToken, ' ') : body;

            // /wizard-ci-snapshots <app> [wizard_ref] [context-mill:<ref>] —
            // wizard_ref defaults to this PR's branch.
            const m = args.match(/\/wizard-ci-snapshots\s+(\S+)(?:\s+(\S+))?/);
            const app = m ? m[1] : 'basic-integration/javascript-node/express-todo';

            // The positional ref also comes from the comment. Check it too.
            const wizardRefArg = m && m[2] ? m[2] : null;
            if (wizardRefArg && !isPlausibleRef(wizardRefArg)) {
              core.setFailed(
                'The wizard ref is not a valid git ref. Use ' +
                  '`/wizard-ci-snapshots <app> <wizard-branch>`.'
              );
              return;
            }
            const wizardRef = wizardRefArg || pr.data.head.ref;

            await github.rest.reactions.createForIssueComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              comment_id: context.payload.comment.id,
              content: 'rocket'
            });

            // Same wizard-ci-trigger dispatch as /wizard-ci, plus snapshots:true —
            // wizard-ci.yml's one SNAPSHOTS branch runs the real-TUI review instead
            // of the evaluator. It checks out its own trusted ref; no untrusted PR
            // code is checked out here.
            await github.rest.repos.createDispatchEvent({
              owner: 'PostHog',
              repo: 'wizard-workbench',
              event_type: 'wizard-ci-trigger',
              client_payload: {
                app: app,
                source: 'wizard-pr',
                source_repo: 'wizard',
                source_pr_number: context.payload.issue.number,
                source_pr_url: pr.data.html_url,
                wizard_ref: wizardRef,
                // Omit the key when unpinned. The workbench then uses `main`.
                ...(contextMillRef ? { context_mill_ref: contextMillRef } : {}),
                notify_slack: 'false',
                notify_pr: 'true',
                snapshots: true
              }
            });

            const pinNote = contextMillRef ? `, context-mill ref ${contextMillRef}` : '';
            console.log(`Triggered snapshots for app: ${app} (ref ${wizardRef}${pinNote})`);

// The MCP client operations every MCP surface shares: detect, add, remove or check, one result per client.
import { logToFile } from '../utils/debug';
import { MCPClient } from './MCPClient';
import { CursorMCPClient } from './clients/cursor';
import { ClaudeCodeMCPClient } from './clients/claude-code';
import { ClaudeWebMCPClient } from './clients/claude-web';
import { ChatGptWebMCPClient } from './clients/chatgpt-web';
import { VisualStudioCodeClient } from './clients/visual-studio-code';
import { ZedClient } from './clients/zed';
import { CodexMCPClient } from './clients/codex';
import { OpenCodeMCPClient } from './clients/opencode';
import { isPluginCapable, PluginCapable } from './plugin-client';
import { toClientResult, type McpClientResult } from './results';

export const getSupportedClients = async (): Promise<MCPClient[]> => {
  const allClients = [
    new ClaudeCodeMCPClient(),
    new ClaudeWebMCPClient(),
    new ChatGptWebMCPClient(),
    new CodexMCPClient(),
    new CursorMCPClient(),
    new VisualStudioCodeClient(),
    new ZedClient(),
    new OpenCodeMCPClient(),
  ];
  const supportedClients: MCPClient[] = [];

  logToFile('Checking for supported MCP clients...');
  for (const client of allClients) {
    const isSupported = await client.isClientSupported();
    logToFile(
      `${client.name}: ${isSupported ? '✓ supported' : '✗ not supported'}`,
    );
    if (isSupported) {
      supportedClients.push(client);
    }
  }
  logToFile(
    `Found ${supportedClients.length} supported client(s): ${supportedClients
      .map((c) => c.name)
      .join(', ')}`,
  );

  return supportedClients;
};

export const getInstalledClients = async (
  local?: boolean,
): Promise<MCPClient[]> => {
  const clients = await getSupportedClients();
  const installedClients: MCPClient[] = [];

  for (const client of clients) {
    // The plugin bundles its own posthog MCP server, so for removal purposes a
    // plugin install counts as installed even with no config entry (`--local`
    // targets only the local-dev entry and leaves the plugin alone).
    const pluginInstalled =
      !local && isPluginCapable(client) && (await client.isPluginInstalled());
    if ((await client.isServerInstalled(local)) || pluginInstalled) {
      installedClients.push(client);
    }
  }

  return installedClients;
};

export const addMCPServer = async (
  clients: MCPClient[],
  personalApiKey?: string,
  selectedFeatures?: string[],
  local?: boolean,
): Promise<McpClientResult[]> => {
  const results: McpClientResult[] = [];
  for (const client of clients) {
    try {
      const result = await client.addServer(
        personalApiKey,
        selectedFeatures,
        local,
      );
      results.push(toClientResult(client.name, result));
    } catch (err) {
      logToFile(`[addMCPServer] addServer threw for ${client.name}: ${err}`);
      results.push(
        toClientResult(client.name, {
          success: false,
          reason: err instanceof Error ? err.message : String(err),
        }),
      );
    }
  }
  return results;
};

export const getSupportedPluginClients = (
  clients: MCPClient[],
): Array<MCPClient & PluginCapable> => {
  return clients.filter(isPluginCapable).filter((c) => c.supportsPlugin());
};

export const installPlugins = async (
  clients: Array<MCPClient & PluginCapable>,
): Promise<McpClientResult[]> => {
  const results: McpClientResult[] = [];
  for (const client of clients) {
    try {
      results.push(toClientResult(client.name, await client.installPlugin()));
    } catch (err) {
      logToFile(
        `[installPlugins] installPlugin threw for ${client.name}: ${err}`,
      );
      results.push(
        toClientResult(client.name, {
          success: false,
          reason: err instanceof Error ? err.message : String(err),
        }),
      );
    }
  }
  return results;
};

export const removeMCPServer = async (
  clients: MCPClient[],
  local?: boolean,
): Promise<McpClientResult[]> => {
  const results: McpClientResult[] = [];
  for (const client of clients) {
    try {
      let result = await client.removeServer(local);
      // The plugin bundles its own posthog server — leaving it installed makes
      // the removal a lie (`--local` never touches the plugin).
      if (!local && isPluginCapable(client) && client.removePlugin) {
        const plugin = await client.removePlugin();
        result =
          !result.success || !plugin.success
            ? {
                success: false,
                reason: [result.reason, plugin.reason]
                  .filter(Boolean)
                  .join('; '),
              }
            : {
                success: true,
                ...(result.alreadyInstalled && plugin.alreadyInstalled
                  ? { alreadyInstalled: true }
                  : {}),
              };
      }
      results.push(toClientResult(client.name, result));
    } catch (err) {
      logToFile(
        `[removeMCPServer] removeServer threw for ${client.name}: ${err}`,
      );
      results.push(
        toClientResult(client.name, {
          success: false,
          reason: err instanceof Error ? err.message : String(err),
        }),
      );
    }
  }
  return results;
};

/**
 * McpInstaller — service layer between McpScreen and MCP business logic.
 *
 * Decouples the screen from step internals. Testable, swappable,
 * no dynamic imports in React components.
 */

import {
  getSupportedClients,
  removeMCPServer,
  getInstalledClients,
  getSupportedPluginClients,
  installPlugins as runPluginInstall,
} from '@shared/mcp-clients/install';
import { ALL_FEATURE_VALUES } from '@shared/mcp-clients/defaults';
import {
  McpClientStatus,
  namesWithStatus,
  redactSecrets,
  toClientResult,
  type McpClientResult,
} from '@shared/mcp-clients/results';
import type { MCPClient } from '@shared/mcp-clients/MCPClient';
import { isPluginCapable } from '@shared/mcp-clients/plugin-client';
import { isLoginCapable } from '@shared/mcp-clients/login-client';
import { isBrowserFinishable } from '@shared/mcp-clients/browser-client';
import { logToFile } from '@utils/debug';
import { analytics } from '@utils/analytics';

/** Where the install lives: a config on this computer, or a connector in the user's account. */
export type McpClientKind = 'local' | 'account';

export interface McpClientInfo {
  name: string;
  kind: McpClientKind;
  supportsPlugin: boolean;
  /** True when the plugin already ships the posthog MCP server (no direct entry needed). */
  pluginBundlesMcp: boolean;
  /**
   * Set for clients connected by opening a hosted page in the browser. The
   * Done screen renders this so the user knows to finish setup in the browser.
   */
  finish?: { url: string; instruction: string };
  /** The editor's own login command (e.g. `claude mcp login posthog`), the one manual step left. */
  loginCommand?: string;
  /** Same, for the plugin-provided server (e.g. `claude mcp login plugin:posthog:posthog`). */
  pluginLoginCommand?: string;
}

export { McpClientStatus };
export type { McpClientResult };

export interface McpInstaller {
  /** Detect which MCP-capable editors are available on this machine. */
  detectClients(): Promise<McpClientInfo[]>;

  /**
   * Install the PostHog MCP server to the given clients. Returns one result per
   * client — including the ones that were already installed and the ones that
   * failed, so the screen can say which happened and why.
   */
  install(
    clientNames: string[],
    features?: string[],
    apiKey?: string,
  ): Promise<McpClientResult[]>;

  /** The local clients that have the PostHog MCP server or plugin installed. */
  detectInstalled(local?: boolean): Promise<McpClientInfo[]>;

  /**
   * Remove the PostHog MCP server from the given installed clients. Returns one
   * result per client so a failed removal isn't reported as a success.
   */
  remove(clientNames: string[], local?: boolean): Promise<McpClientResult[]>;

  /** Install the PostHog AI plugin to supported clients. Best-effort: failures do not affect MCP outcome. */
  installPlugins(clientNames: string[]): Promise<McpClientResult[]>;
}

/**
 * Production McpInstaller backed by real MCP client detection and installation.
 */
const toClientInfo = (c: MCPClient): McpClientInfo => ({
  name: c.name,
  kind: isBrowserFinishable(c) ? 'account' : 'local',
  supportsPlugin: isPluginCapable(c) && c.supportsPlugin(),
  pluginBundlesMcp: isPluginCapable(c) && c.pluginBundlesMcpServer(),
  finish: isBrowserFinishable(c)
    ? { url: c.connectorUrl, instruction: c.finishInstruction }
    : undefined,
  loginCommand: (isLoginCapable(c) && c.loginCommand(false)) || undefined,
  pluginLoginCommand:
    (isLoginCapable(c) && c.pluginLoginCommand?.()) || undefined,
});

export function createMcpInstaller(): McpInstaller {
  // Cache the raw MCPClient objects so install() can reference them by name
  let cachedClients: Array<{ name: string; raw: unknown }> = [];
  // Same for remove(): the clients detectInstalled() found.
  let installedClients: MCPClient[] = [];

  return {
    async detectClients(): Promise<McpClientInfo[]> {
      const supported = await getSupportedClients();
      cachedClients = supported.map((c) => ({ name: c.name, raw: c }));
      return supported.map(toClientInfo);
    },

    async detectInstalled(local?: boolean): Promise<McpClientInfo[]> {
      // Account clients live in the user's account, so there is nothing local
      // to remove; they never report installed, and this keeps it that way.
      installedClients = (await getInstalledClients(local)).filter(
        (c) => !isBrowserFinishable(c),
      );
      return installedClients.map(toClientInfo);
    },

    async install(
      clientNames: string[],
      features?: string[],
      apiKey?: string,
    ): Promise<McpClientResult[]> {
      const resolvedFeatures = features ?? [...ALL_FEATURE_VALUES];
      const toInstall = cachedClients
        .filter((c) => clientNames.includes(c.name))
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .map((c) => c.raw as any);

      if (toInstall.length === 0) {
        logToFile(
          `[McpInstaller] No clients matched. clientNames=${JSON.stringify(
            clientNames,
          )}, cached=${JSON.stringify(cachedClients.map((c) => c.name))}`,
        );
        return [];
      }

      const results: McpClientResult[] = [];
      for (const client of toInstall) {
        const name = client.name as string;
        try {
          const result = await client.addServer(
            apiKey,
            resolvedFeatures,
            false,
          );
          results.push(toClientResult(name, result));
          if (!result?.success) {
            // redactSecrets, not the raw reason: the CLIs we shell out to echo
            // the Authorization header back in their error output.
            logToFile(
              `[McpInstaller] addServer returned success=false for ${name}: ${redactSecrets(
                result?.reason ?? 'no reason given',
              )}`,
            );
          }
        } catch (err) {
          const reason = err instanceof Error ? err.message : String(err);
          logToFile(
            `[McpInstaller] addServer threw for ${name}: ${redactSecrets(
              reason,
            )}`,
          );
          results.push(toClientResult(name, { success: false, reason }));
        }
      }
      return results;
    },

    async remove(
      clientNames: string[],
      local?: boolean,
    ): Promise<McpClientResult[]> {
      // `local` was dropped here, so `mcp remove --local` looked at (and
      // reported on) the wrong server name.
      const selected = installedClients.filter((c) =>
        clientNames.includes(c.name),
      );
      if (selected.length === 0) return [];
      return removeMCPServer(selected, local);
    },

    async installPlugins(clientNames: string[]): Promise<McpClientResult[]> {
      const rawClients = cachedClients
        .filter((c) => clientNames.includes(c.name))
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .map((c) => c.raw as any);

      const pluginClients = getSupportedPluginClients(rawClients);
      const results = await runPluginInstall(pluginClients);

      const already = namesWithStatus(results, McpClientStatus.Unchanged);
      analytics.wizardCapture('mcp plugins installed', {
        // `clients` keeps its original meaning — every client that ended up with
        // the plugin — so existing insights don't dip when a re-run reports
        // already-installed instead of a fresh write.
        clients: [
          ...namesWithStatus(results, McpClientStatus.Changed),
          ...already,
        ],
        already_installed: already,
        attempted: pluginClients.map((c) => c.name),
      });

      return results;
    },
  };
}

/**
 * Compaction event tracking plugin.
 *
 * Tracks context compaction events (compact_boundary system messages)
 * including pre-compaction token counts per phase.
 */

import type { Middleware, MiddlewareContext, MiddlewareStore } from '../types';
import { logToFile } from '@utils/debug';
import { AgentSignals } from '../../agent-interface';

export interface CompactionData {
  phaseCompactions: number;
  phasePreTokens: number[];
  totalCompactions: number;
  phaseSnapshots: Array<{
    phase: string;
    compactions: number;
    preTokens: number[];
  }>;
}

export class CompactionTrackerPlugin implements Middleware {
  readonly name = 'compactions';

  private phaseCompactions = 0;
  private phasePreTokens: number[] = [];
  private totalCompactions = 0;
  private phaseSnapshots: Array<{
    phase: string;
    compactions: number;
    preTokens: number[];
  }> = [];
  private currentPhase = 'setup';

  onMessage(
    message: any,
    ctx: MiddlewareContext,
    store: MiddlewareStore,
  ): void {
    if (message.type !== 'system' || message.subtype !== 'compact_boundary') {
      return;
    }

    const preTokens = message.compact_metadata?.pre_tokens ?? 0;
    const trigger = message.compact_metadata?.trigger ?? 'unknown';
    this.phaseCompactions++;
    this.totalCompactions++;
    this.phasePreTokens.push(preTokens);

    logToFile(
      `${AgentSignals.BENCHMARK} [COMPACTION] Context compacted during "${ctx.currentPhase}" (trigger: ${trigger}, pre_tokens: ${preTokens})`,
    );

    store.set('compactions', this.getData());
  }

  onPhaseTransition(
    fromPhase: string,
    toPhase: string,
    _ctx: MiddlewareContext,
    store: MiddlewareStore,
  ): void {
    this.phaseSnapshots.push({
      phase: fromPhase,
      compactions: this.phaseCompactions,
      preTokens: [...this.phasePreTokens],
    });
    this.currentPhase = toPhase;
    this.phaseCompactions = 0;
    this.phasePreTokens = [];
    store.set('compactions', this.getData());
  }

  onFinalize(
    _resultMessage: any,
    _totalDurationMs: number,
    _ctx: MiddlewareContext,
    store: MiddlewareStore,
  ): void {
    this.phaseSnapshots.push({
      phase: this.currentPhase,
      compactions: this.phaseCompactions,
      preTokens: [...this.phasePreTokens],
    });
    store.set('compactions', this.getData());
  }

  private getData(): CompactionData {
    return {
      phaseCompactions: this.phaseCompactions,
      phasePreTokens: [...this.phasePreTokens],
      totalCompactions: this.totalCompactions,
      phaseSnapshots: [...this.phaseSnapshots],
    };
  }
}

/**
 * Shared preparation for the runner pipeline.
 *
 * Runs before the fork into the linear or orchestrator arm: logging targets,
 * the gateway mint and the scan-triage classifier built on it. Everything the
 * caller must decide first — health gates, settings conflicts, authentication,
 * the AI opt-in gate, post-auth gates, feature flags, run tags, token refresh —
 * arrives already resolved in `ResolvedRunConfig` and `RunInput`.
 */

import { createTriageLLMProvider } from '../../triage-provider';
import { gatewayAuth } from '../../gateway-session';
import { currentAccessToken } from '@shared/oauth-session';
import { logToFile } from '@utils/debug';
import { CallType, IS_DEV } from '@shared/constants';
import { VERSION } from '@shared/version';
import { mcpUrlFor } from '@shared/host-resolution';
import type { WizardRunOptions } from '@utils/types';
import type { BootstrapResult, ResolvedRunConfig, RunInput } from './types';

// ── Helpers ──────────────────────────────────────────────────────────

/** The option bag the agent interface and the middleware read. */
export function runOptions(input: RunInput): WizardRunOptions {
  return {
    installDir: input.installDir,
    debug: input.flags.debug,
    signup: input.flags.signup,
    ci: input.flags.ci,
    benchmark: input.flags.benchmark,
    projectId: input.host.projectId,
    apiKey: [REDACTED],
    yaraReport: input.flags.yaraReport,
  };
}

// ── Prepare ───────────────────────────────────────────────────────────

/**
 * Shared setup for both arms: logging targets, then the gateway mint and the
 * triage classifier. Throws when the mint is refused, so the run fails before
 * any agent starts — the caller maps that the way it maps any unexpected error.
 */
export async function prepareRun(
  config: ResolvedRunConfig,
  input: RunInput,
): Promise<BootstrapResult> {
  const { skillsBaseUrl } = config;

  // Where this run actually points. The three services switch independently,
  // so otherwise "why did it use prod skills?" means reading three call sites.
  logToFile(
    `[agent-runner] targets build=${VERSION}${IS_DEV ? '/dev' : ''} ` +
      `skills=${skillsBaseUrl} ` +
      `mcp=${mcpUrlFor(input.flags.localMcp)} ` +
      `posthog=${input.host.baseUrl ?? 'region-resolved'}`,
  );

  const { credentials } = input;
  const { wizardFlags, wizardFlagPayloads, wizardMetadata, programId } = config;

  // Mint now so a refusal fails the boot before any agent starts. Later
  // readers re-resolve through the cache, which re-mints past the refresh
  // point.
  const currentGatewayAuth = () =>
    // TODO: the agent must not mint inference auth. It receives the
    // PostHog token here and derives a gateway token from it, re-minting near
    // expiry. Programs own credentials (stack plan 4.5): pass a resolved
    // inference-auth provider on RunInput.credentials and move
    // gateway-session.ts out of src/agent with it.
    currentAccessToken(credentials).then((token) =>
      gatewayAuth(credentials.host, token, programId),
    );
  await currentGatewayAuth();

  return {
    skillsBaseUrl,
    credentials,
    // Carried so per-task sessions re-resolve against the same program the boot
    // minted for, rather than digging it back out of the metadata bag.
    programId,
    handoffNotebook: config.handoffNotebook,
    wizardFlags,
    wizardFlagPayloads,
    wizardMetadata,
    project: input.project,
    // Resolved once, here: the only place holding both the run-level harness
    // and the gateway auth. Every skill install downstream reads it off boot.
    triageProvider: createTriageLLMProvider(async () => {
      const auth = await currentGatewayAuth();
      return {
        baseURL: auth.gatewayUrl,
        authToken: auth.token,
        teamId: auth.teamId,
        // `call_type` splits scan spend out of the program's agent cost,
        // the same tag the in-run triage provider carries.
        wizardMetadata: { ...wizardMetadata, call_type: CallType.yaraTriage },
        wizardFlags,
      };
    }, config.binding.harness),
  };
}

import type { Arguments } from 'yargs';
import { consoleLog } from '@shared/console-log';
import { API_KEY_HINT, runWizardCI, runWizardHeadless } from '@cli/runners';
import type { NonInteractiveMode } from '@headless';
import { provisionNewAccount } from '@utils/provisioning';
import { config as posthogIntegrationConfig } from '@programs/posthog-integration';
import { ErrorCodes, type ErrorCode } from '@shared/errors';
import { emitWizardError } from '@shared/errors';

type Options = Arguments & {
  region?: string;
  baseUrl?: string;
  installDir?: string;
  apiKey?: string;
  signup?: boolean;
  email?: string;
  name?: string;
  projectId?: string;
};

/**
 * CI-mode install entry point (`--ci`, dev/test builds). Thin shell over the
 * shared non-interactive install — see `runNonInteractiveInstall`.
 */
export function runCIInstall(argv: Arguments): void {
  runNonInteractiveInstall(argv, 'ci');
}

/**
 * Headless install entry point (the experimental published-build run path; see
 * @shared/headless-mode). Thin shell over the shared non-interactive install.
 * Today it behaves exactly like `runCIInstall`; it is a separate function so
 * headless can diverge later (auth, prompts, …) without touching the CI path.
 */
export function runHeadlessInstall(argv: Arguments): void {
  runNonInteractiveInstall(argv, 'headless');
}

/**
 * Non-interactive install shared by CI and headless. Validates signup flags,
 * optionally provisions an account, then installs. `mode` only changes
 * user-facing labels and which runner is invoked; the accepted keys and the
 * install itself are identical (see runNonInteractive).
 */
function runNonInteractiveInstall(
  argv: Arguments,
  mode: NonInteractiveMode,
): void {
  const options = { ...argv } as Options;
  const headless = mode === 'headless';
  const label = headless ? 'Headless' : 'CI';
  const runWizard = headless ? runWizardHeadless : runWizardCI;

  // Base validation (region/install-dir/api-key) is owned by the runner.
  // This layer only adds the signup branch on top.
  if (!options.apiKey && !options.signup) {
    return failCI(
      `${label} mode requires --api-key (${API_KEY_HINT}). ` +
        'To create a new account instead, use --signup --email you@example.com.',
      ErrorCodes.ArgsMissingApiKey,
    );
  }
  if (!options.apiKey && options.signup && !options.email) {
    return failCI(
      `${label} --signup requires --email to create a new account.`,
      ErrorCodes.ArgsMissingEmail,
    );
  }
  warnOnUnexpectedKeyPrefix(options.apiKey);

  void (async () => {
    if (!options.apiKey && options.signup) {
      // Fail before the irreversible provisioning step rather than after it.
      if (!options.installDir) {
        return failCI(
          `${label} mode requires --install-dir (directory to install in)`,
          ErrorCodes.ArgsMissingInstallDir,
        );
      }
      const provisioned = await provisionForSignup(options);
      options.apiKey = [REDACTED];
      if (options.projectId == null) options.projectId = provisioned.projectId;
    }
    runWizard(posthogIntegrationConfig, options);
  })().catch((error: unknown) => {
    emitWizardError({
      code: ErrorCodes.ArgsSignupProvisionFailed,
      message: error instanceof Error ? error.message : String(error),
    });
    process.exit(1);
  });
}

function failCI(message: string, code?: ErrorCode): void {
  consoleLog.intro('PostHog Wizard');
  consoleLog.log.error(message);
  if (code) emitWizardError({ code, message });
  process.exit(1);
}

/**
 * Decide whether to warn about an unexpected `--api-key` prefix, and with what
 * message. Returns `null` when the key is acceptable.
 *
 * CI and headless accept the same two credentials: a personal API key (`phx_`)
 * and a `pha_` OAuth access token minted under the wizard's own OAuth
 * application (cloud runs, and the CI bot). Both authenticate the mint the
 * same way. Anything else is unexpected and warns.
 *
 * Extracted as a pure predicate so it can be unit-tested without a UI.
 */
export function keyPrefixWarning(apiKey: string | undefined): string | null {
  if (!apiKey || apiKey.startsWith('phx_') || apiKey.startsWith('pha_')) {
    return null;
  }
  const hint = apiKey.startsWith('phc_')
    ? ' (phc_ is a project/client key; expected a personal API key or a wizard-app token)'
    : '';
  return `--api-key does not start with "phx_" or "pha_"${hint}. Continuing anyway, but the LLM Gateway may reject it with a 401.`;
}

function warnOnUnexpectedKeyPrefix(apiKey: string | undefined): void {
  const message = keyPrefixWarning(apiKey);
  if (!message) return;
  consoleLog.intro('PostHog Wizard');
  consoleLog.log.warn(message);
}

/**
 * Provision a new account and return its credentials. Throws on any failure
 * (after logging a user-facing message); the caller's `.catch` turns that
 * into a non-zero exit. The return type carries no failure sentinel.
 */
async function provisionForSignup(
  options: Options,
): Promise<{ personalApiKey: string; projectId: string }> {
  consoleLog.intro('PostHog Wizard');
  const signupRegion = ((options.region as string) || 'us').toUpperCase() as
    | 'US'
    | 'EU';
  consoleLog.log.info(
    `Provisioning new PostHog account for ${String(
      options.email,
    )} in ${signupRegion}...`,
  );

  let result;
  try {
    result = await provisionNewAccount(
      options.email as string,
      options.name ?? '',
      signupRegion,
      { baseUrl: options.baseUrl },
    );
  } catch (error) {
    const msg = error instanceof Error ? error.message : String(error);
    consoleLog.log.error(`Provisioning failed: ${msg}`);
    throw error;
  }

  if (!result.personalApiKey) {
    consoleLog.log.error(
      'Provisioning succeeded but no personal API key was returned — cannot continue install.',
    );
    throw new Error('provisioning returned no personal API key');
  }

  consoleLog.log.success('Account ready.');
  consoleLog.log.info(`  Project API Key:  ${result.projectApiKey}`);
  consoleLog.log.info(`  Personal API Key: ${result.personalApiKey}`);
  consoleLog.log.info(`  Host:             ${result.host}`);
  return {
    personalApiKey: [REDACTED],
    projectId: result.projectId,
  };
}

/**
 * wizard-ci-mcp — MCP server that lets an agent drive the REAL wizard TUI.
 *
 * A thin proxy: it spawns the shared real-TUI host (scripts/tui-host.no-jest.ts,
 * MODE=serve) in a PTY via the Node capturer, forwards read_state/perform_action/
 * run_agent to it over a unix socket, and returns the REAL rendered screen for
 * render_screen. No store or rendering lives here — same host the CI snapshot
 * route uses. stdout is the JSON-RPC channel; nothing else writes to it.
 *
 * Registered in this repo's `.mcp.json`, so the tools are bound in every session.
 */
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';
import fs from 'fs';
import os from 'os';
import path from 'path';
import net from 'net';
import { captureTui, type TuiCapture } from '@e2e-harness/tui-capture';

const text = (data: unknown) => ({
  content: [
    {
      type: 'text' as const,
      text: typeof data === 'string' ? data : JSON.stringify(data, null, 2),
    },
  ],
});
const errorOut = (e: unknown) => ({
  content: [
    {
      type: 'text' as const,
      text: `Error: ${e instanceof Error ? e.message : String(e)}`,
    },
  ],
  isError: true,
});

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

let cap: TuiCapture | null = null;
let sockPath = '';

/** One request/response over the host's control socket (newline-delimited JSON). */
function rpc(req: object): Promise<{
  ok: boolean;
  state?: unknown;
  error?: string;
  runStatus?: string;
}> {
  return new Promise((resolve, reject) => {
    if (!sockPath)
      return reject(new Error('No app open. Call open_app first.'));
    const sock = net.connect(sockPath);
    let buf = '';
    const timer = setTimeout(() => {
      sock.destroy();
      reject(new Error('control socket timeout'));
    }, 600_000);
    sock.on('connect', () => sock.write(JSON.stringify(req) + '\n'));
    sock.on('data', (d) => {
      buf += d;
      const i = buf.indexOf('\n');
      if (i >= 0) {
        clearTimeout(timer);
        sock.end();
        resolve(JSON.parse(buf.slice(0, i)));
      }
    });
    sock.on('error', (e) => {
      clearTimeout(timer);
      reject(e);
    });
  });
}

async function waitFor(cond: () => boolean, ms: number): Promise<boolean> {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    if (cond()) return true;
    await sleep(150);
  }
  return false;
}

async function main() {
  const server = new McpServer({ name: 'wizard-ci', version: '1.0.0' });

  server.tool(
    'open_app',
    'Boot the real wizard TUI on an app and make it active. Call once before the other tools. appDir is a throwaway copy of the app to integrate. Returns the first screen.',
    {
      appDir: z
        .string()
        .describe('Absolute path to the app (a throwaway /tmp copy)'),
      keyFile: z
        .string()
        .optional()
        .describe(
          'Absolute path to a file holding the PostHog phx key (preferred)',
        ),
      apiKey: z
        .string()
        .optional()
        .describe('The phx key inline (prefer keyFile to keep it out of logs)'),
      projectId: z.string().describe('PostHog project id the key is scoped to'),
      region: z
        .enum(['us', 'eu'])
        .optional()
        .describe('PostHog region (default us)'),
    },
    async ({ appDir, keyFile, apiKey, projectId, region }) => {
      try {
        if (cap) cap.kill();
        const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'wizard-ci-'));
        sockPath = path.join(dir, 'host.sock');
        // Strip the host's Claude Code / Anthropic auth so the wizard's agent
        // subprocess authenticates with the phx key instead of deferring to the
        // host session (which yields apiKeySource=none → 401).
        const env: NodeJS.ProcessEnv = { ...process.env };
        for (const k of Object.keys(env))
          if (/^(CLAUDE|ANTHROPIC|AI_AGENT)/.test(k)) delete env[k];
        Object.assign(env, {
          MODE: 'serve',
          CONTROL_SOCK: sockPath,
          SNAP_CTRL: path.join(dir, 'ctrl'),
          APP_DIR: appDir,
          PROJECT_ID: projectId,
          POSTHOG_REGION: region ?? 'us',
          // Pass the key the way the caller gave it; never write an inline key to
          // disk. The host reads either form (POSTHOG_PERSONAL_API_KEY wins).
          ...(keyFile
            ? { POSTHOG_KEY_FILE: keyFile }
            : { POSTHOG_PERSONAL_API_KEY: (apiKey ?? '').trim() }),
        });
        cap = captureTui({
          cmd: path.join(process.cwd(), 'node_modules/.bin/tsx'),
          args: [
            '--tsconfig',
            'tsconfig.base.json',
            'scripts/tui-host.no-jest.ts',
          ],
          cwd: process.cwd(),
          env,
        });
        if (!(await waitFor(() => fs.existsSync(sockPath), 30_000)))
          return errorOut(new Error('the TUI host did not start'));
        await waitFor(() => cap!.frame().includes('PostHog'), 30_000);
        const r = await rpc({ type: 'read_state' });
        return text(r.state ?? r);
      } catch (e) {
        return errorOut(e);
      }
    },
  );

  server.tool(
    'read_state',
    "Read the wizard's committed state: current screen, run phase, a secret-free session view, tasks, pending question, and the actions legal now. Call after every perform_action and to poll run_agent (integration: running → done).",
    {},
    async () => {
      try {
        const r = await rpc({ type: 'read_state' });
        return text(r.state ?? r);
      } catch (e) {
        return errorOut(e);
      }
    },
  );

  server.tool(
    'perform_action',
    'Commit a decision on the current screen (confirm_setup, dismiss_outage, choose, set_mcp_outcome, dismiss_slack, keep_skills). The action must appear in read_state.actions. Returns the next state.',
    {
      action: z.string().describe('Action id from read_state.actions'),
      params: z
        .record(z.string(), z.unknown())
        .optional()
        .describe('Action params, e.g. { key: "router", value: "app-router" }'),
    },
    async ({ action, params }) => {
      try {
        const r = await rpc({
          type: 'perform_action',
          action,
          params: params ?? {},
        });
        return text(r.state ?? r);
      } catch (e) {
        return errorOut(e);
      }
    },
  );

  server.tool(
    'render_screen',
    'Return the REAL rendered TUI screen (ANSI-stripped text) — exactly what the user would see.',
    {},
    async () => {
      try {
        if (!cap) throw new Error('No app open. Call open_app first.');
        await sleep(150); // let the emulator apply the latest frame
        return text(cap.frame());
      } catch (e) {
        return errorOut(e);
      }
    },
  );

  server.tool(
    'run_agent',
    'Kick off the real integration in the background and return immediately. It advances the auth and run screens (they never advance on their own). Then poll read_state — integration goes running → done and currentScreen advances to outro, or → failed with the reason in integrationError. Creates real PostHog resources (a dashboard + insights). Call once setup is confirmed.',
    {},
    async () => {
      try {
        const r = await rpc({ type: 'run_agent' });
        return text({
          status:
            'integration started in the background — poll read_state (integration: running → done; screen advances to outro)',
          ...r,
        });
      } catch (e) {
        return errorOut(e);
      }
    },
  );

  await server.connect(new StdioServerTransport());
  process.stderr.write('wizard-ci-mcp: proxy ready on stdio\n');
}

main().catch((e) => {
  process.stderr.write(`wizard-ci-mcp fatal: ${e?.stack ?? e}\n`);
  process.exit(1);
});

/**
 * Fail-closed security for the pi backend (#525). pi has no built-in
 * permission layer, so we attach an extension that intercepts every tool call
 * — built-in (bash/read/edit/write/grep) AND custom — through pi's `tool_call`
 * hook and reuses the shared tool policy: `wizardCanUseTool` (the bash fence,
 * whose one `rm` rule is project-scoped, + .env fencing) plus the YARA
 * pre-scan. A `tool_result` hook
 * post-scans output. Both fail closed: a scanner error blocks, and a critical
 * post-scan violation latches so every subsequent tool call is blocked and the
 * run terminates as a YARA violation.
 *
 * Scanning runs through @posthog/warlock via yara-hooks' `scanAndTriage` — the
 * same engine, rules, chunking, and LLM triage policy as the anthropic
 * harness. pi handlers are async (pi's ExtensionHandler accepts promises), so
 * the WASM scan awaits inline.
 *
 * This is the one fence. Subagents run their own pi session with its subagent
 * gate installed (see subagent.ts): the same fence and state, with no `rm`.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import type { LLMProvider, ScanMatch } from '@posthog/warlock';
import { wizardCanUseTool } from '../../../agent-interface';
import {
  createRepeatBlockTracker,
  isWizardDocumentationPath,
  recordExternalScan,
  repeatBlockReason,
  scanAndTriage,
  type RepeatBlockTracker,
} from '../../../yara-hooks';
import {
  publishBlockingMatch,
  scanVerdict,
  type ScanContext,
} from '../../../yara-policy';
import { logToFile } from '@utils/debug';
import { analytics } from '@utils/analytics';

/** warlock ScanMatch → the report shape `recordExternalScan` expects. */
function toReportViolation(m: ScanMatch) {
  return {
    rule: m.rule,
    severity: m.metadata.severity ?? 'unknown',
    category: m.metadata.category ?? 'unknown',
    description: m.metadata.description ?? '',
  };
}

/** Runaway backstop: hard cap on tool calls per (sub)agent session. */
export const MAX_TOOL_CALLS = 250;

/**
 * Passive telemetry for an unfixed upstream failure: gpt-5.x streaming with
 * tools leaks its function-call grammar into string values, and the leak lands
 * on disk (run 9704a73e shipped `…functions.complete_task (commentary…` plus a
 * DEL byte inside a customer's global-error.tsx). Observe-only — never blocks.
 * Prior art: https://github.com/BerriAI/litellm/issues/14260 (closed stale),
 * https://community.openai.com/t/1386422 (gpt-5.6-luna, no fix).
 */
const TRANSPORT_LEAK_PATTERNS: readonly { pattern: RegExp; label: string }[] = [
  // The litellm#14260 signature, scoped to the wizard's own tool names — a
  // generic `functions.*` would false-positive on real code (Firebase).
  {
    pattern: /functions\.(?:complete_task|enqueue_task|read_handoffs)/,
    label: 'leaked tool-call tokens',
  },
  {
    pattern: /<\|(?:channel|constrain|message|call|end|start|return)\|>/,
    label: 'leaked channel markers',
  },
  // C0 controls and DEL minus tab/newline/CR — never valid in source text.
  // eslint-disable-next-line no-control-regex
  { pattern: /[\0-\x08\x0B\f\x0E-\x1F\x7F]/, label: 'control characters' },
];

/** Capture one event per leaking write/edit: which pattern fired and where it sat — no matched text, ever. */
export function observeTransportLeak(tool: string, content: string): void {
  for (const { pattern, label } of TRANSPORT_LEAK_PATTERNS) {
    const match = pattern.exec(content);
    if (!match) continue;
    analytics.wizardCapture('file content leak observed', {
      tool,
      leak: label,
      leak_offset: match.index,
      content_length: content.length,
      // End-of-string leaks are the upstream decoder signature.
      at_end: content.length - match.index < 80,
    });
    logToFile(
      `[transport-leak] observed ${tool}: ${label} at ${match.index}/${content.length}`,
    );
    return;
  }
}

export const READ_ONLY_PI_TOOLS: ReadonlySet<string> = new Set([
  'read',
  'grep',
  'find',
  'ls',
]);

export interface ToolGateContext {
  readOnly?: boolean;
  disallowedTools?: readonly string[];
  /** True while a wizard_ask overlay is open (interactive); blocks Write/Edit. */
  getWizardAskPending?: () => boolean;
  /** Scan-triage classifier, resolved once in bootstrap. Absent → every flagged match is acted on. */
  triageProvider?: LLMProvider;
  /**
   * Per-run tracker of YARA-blocked payloads. When the agent retries content
   * that was already blocked, the block reason escalates ("change the code,
   * not the retry" → "report it and move on"). The extension wires one in;
   * absent (tests calling `evaluateToolCall` directly) every block reads as
   * a first attempt.
   */
  repeatTracker?: RepeatBlockTracker;
  /** Project root; rm is only allowed for files resolving strictly inside it. */
  workingDirectory?: string;
}

export interface GateDecision {
  block: boolean;
  reason?: string;
  /** End the run, don't just refuse the call. Set when a blocked publish_handoff would otherwise leave no report. */
  terminate?: boolean;
}

const str = (v: unknown): string => (typeof v === 'string' ? v : '');

/** A pi tool path as pi opens it: its `resolveToCwd` strips a leading `@` and decodes `file://`. */
function piToolPath(v: unknown): string {
  const raw = str(v);
  const p = raw.startsWith('@') ? raw.slice(1) : raw;
  if (!p.startsWith('file://')) return p;
  try {
    return fileURLToPath(p);
  } catch {
    return p; // pi fails to open it too
  }
}

// Shell metacharacters that chain, substitute, or redirect. A command carrying
// any of these is more than one action, so we never treat it as a plain `rm`.
const SHELL_OPERATORS = /[;&|`$(){}<>\n'"\\]/;

/** True when a target resolves to a file strictly inside the project root. */
function isDeletableProjectFile(
  target: string,
  root: string,
  p: typeof path,
): boolean {
  if (target.startsWith('-')) return false; // a flag, not a file
  if (/[*?[\]~]/.test(target)) return false; // glob / home expansion
  if (p.basename(target).startsWith('.env')) return false; // secrets

  const canonicalRoot = p.resolve(root);
  const resolved = p.resolve(canonicalRoot, target);
  return (
    resolved !== canonicalRoot && resolved.startsWith(canonicalRoot + p.sep)
  );
}

/**
 * A plain `rm [-f] <file...>` whose every target is a file inside the project
 * root — the deletion shape the anthropic arm permits (there bash isn't
 * allowlisted; the shared YARA destructive-delete rules catch the dangerous
 * forms). pi rescues the same shape so the fall-through YARA scan can judge
 * it, but refuses any shell operator so it can't smuggle a second command.
 * Path checks run through the host's `path` (win32 on Windows, posix elsewhere);
 * pi always executes commands via a POSIX bash, so targets use forward slashes.
 */
export function isScopedFileRemoval(
  command: string,
  rawRoot: string | undefined,
  p: typeof path = path,
): boolean {
  if (!rawRoot) return false; // no root to contain against → never rescue
  const root = p.resolve(rawRoot);
  const trimmed = command.trim();
  if (SHELL_OPERATORS.test(trimmed)) return false;

  const [executable, ...args] = trimmed.split(/\s+/);
  if (executable !== 'rm') return false;

  if (args[0] === '-f') args.shift();
  if (args.length === 0) return false;

  return args.every((arg) => isDeletableProjectFile(arg, root, p));
}

/** A write that removes more than this fraction of an existing file's
 * non-whitespace content reads as a destructive whole-file rewrite. */
const OVERWRITE_SHRINK_LIMIT = 0.3;

/** Existing files below this many non-whitespace chars are stubs; replacing one
 * wholesale is legitimate, so the shrink guard leaves them alone. */
const OVERWRITE_MIN_CHARS = 400;

const nonWhitespaceLength = (s: string): number => s.replace(/\s+/g, '').length;

/**
 * Refuse a write that replaces an existing file with far less content than it
 * held, steering the agent back to targeted edits. Prior art — the destructive
 * whole-file rewrite is a known model failure that targeted-edit formats exist to
 * prevent: Aider's search/replace and unified-diff, OpenAI's apply_patch,
 * Anthropic's str_replace with replace_all; pi's edit tool has no replace_all, so
 * a rejected scoped edit can fall back to a lossy full write. Additive by design:
 * the wizard only adds instrumentation, so a large shrink is the rewrite, not intent.
 */
export function overwriteShrinkReason(
  existing: string,
  next: string,
): string | undefined {
  const before = nonWhitespaceLength(existing);
  if (before < OVERWRITE_MIN_CHARS) return undefined;
  const after = nonWhitespaceLength(next);
  if (after >= before * (1 - OVERWRITE_SHRINK_LIMIT)) return undefined;
  const removed = Math.round((1 - after / before) * 100);
  return `This write replaces an existing file and removes ~${removed}% of its content. Make targeted edits instead of rewriting the whole file; only write a file in full when creating it.`;
}

/**
 * Read the file a write would replace and flag a destructive shrink. A path that
 * does not exist yet is a new file, so it never triggers; with no project root to
 * resolve against (unit tests calling `evaluateToolCall` bare), it stays inert.
 */
async function overwriteShrinkBlock(
  input: Record<string, unknown>,
  workingDirectory: string | undefined,
): Promise<string | undefined> {
  const target = piToolPath(input.path);
  if (!workingDirectory || !target) return undefined;
  let existing: string;
  try {
    existing = await fs.promises.readFile(
      path.resolve(workingDirectory, target),
      'utf8',
    );
  } catch {
    return undefined; // new file (ENOENT) or unreadable — nothing to preserve
  }
  return overwriteShrinkReason(existing, str(input.content));
}

/**
 * Translate a pi tool name to the claude-cased name + input the shared policy
 * expects. pi field names (from the live tool stream): bash{command},
 * read/edit/write{path}, write adds {content}, edit adds {edits}, grep{path}.
 */
function toClaudePolicyCall(
  toolName: string,
  input: Record<string, unknown>,
): { name: string; input: Record<string, unknown> } {
  switch (toolName) {
    case 'bash':
      return { name: 'Bash', input: { command: str(input.command) } };
    case 'read':
      return { name: 'Read', input: { file_path: piToolPath(input.path) } };
    case 'write':
      return { name: 'Write', input: { file_path: piToolPath(input.path) } };
    case 'edit':
      return { name: 'Edit', input: { file_path: piToolPath(input.path) } };
    case 'grep':
      return {
        name: 'Grep',
        input: { path: piToolPath(input.path), glob: input.glob },
      };
    default:
      // Custom tools (load_skill_menu, set_env_values, dispatch_agent, …) +
      // find/ls: no path/command, policy allows (their own handlers are fenced).
      return { name: toolName, input };
  }
}

/**
 * The agent-facing block message. Includes the rule's remediation so a blocked
 * agent can self-correct (e.g. "move PII to identify()/$set") instead of
 * retrying near-identical content.
 */
function blockMessage(m: ScanMatch): string {
  const remediation = m.metadata.remediation
    ? ` Fix: ${m.metadata.remediation}.`
    : '';
  return `[YARA] ${m.rule}: ${
    m.metadata.description ?? 'security rule matched'
  }.${remediation} Blocked for security.`;
}

/**
 * YARA scan of the content a tool is about to act on, BEFORE it executes.
 * - bash → scan the command ('command'-context rules: exfiltration,
 *   destructive, force-push). No triage — a flagged command always blocks,
 *   same as the anthropic PreToolUse hook, so the LLM call would be wasted.
 * - write/edit → scan the content being written ('output'-context rules:
 *   hardcoded keys, PII), WITH triage, and with the same wizard-doc
 *   `posthog_pii` suppression the anthropic path uses so the agent's own
 *   event-plan files aren't blocked.
 * - publish_handoff → scan the report ('output'-context rules) with triage,
 *   but only a CRITICAL match refuses the publish — it's the only channel.
 * Returns a block reason, or undefined to allow. Read/grep are post-scanned on
 * their output (in the tool_result hook), not here.
 */
async function preExecutionYaraBlock(
  toolName: string,
  input: Record<string, unknown>,
  llmProvider: LLMProvider | undefined,
  repeatTracker?: RepeatBlockTracker,
): Promise<string | undefined> {
  let content: string;
  let ctx: ScanContext;
  let triage: LLMProvider | undefined;
  // Report labels for the scan report (phase/tool), matching the anthropic
  // hooks so pi and anthropic runs read the same in telemetry.
  let phase: string;
  let tool: string;
  switch (toolName) {
    case 'bash':
      content = str(input.command);
      ctx = 'command';
      triage = undefined;
      phase = 'PreToolUse';
      tool = 'Bash';
      break;
    case 'write':
      content = str(input.content);
      ctx = 'output';
      triage = llmProvider;
      phase = 'PostToolUse';
      tool = 'Write';
      break;
    case 'edit':
      // Scan ONLY the replacement text. `edits` is [{oldText, newText}] and
      // oldText is pre-existing file content the agent is changing — scanning
      // it blocks edits whose *surroundings* contain a violation, and even
      // edits that are removing one (field FPs: capture edits adjacent to
      // existing identify() PII; pre-existing violations blocking their own
      // replacement). Matches the anthropic path, which scans new_string only.
      content = (Array.isArray(input.edits) ? input.edits : [])
        .map((e) => str((e as Record<string, unknown>)?.newText))
        .join('\n');
      ctx = 'output';
      triage = llmProvider;
      phase = 'PostToolUse';
      tool = 'Edit';
      break;
    case 'publish_handoff':
      // Agent-authored content persisted to the task stream and the host file.
      // Own labels, not Write's — the block bar differs (critical only).
      content = str(input.content);
      ctx = 'output';
      triage = llmProvider;
      phase = 'PreToolUse';
      tool = 'publish_handoff';
      break;
    default:
      return undefined;
  }
  if (!content) return undefined;
  if (ctx === 'output') observeTransportLeak(tool, content);

  let matches = await scanAndTriage(content, ctx, triage);
  if (ctx === 'output' && isWizardDocumentationPath(piToolPath(input.path))) {
    matches = matches.filter((m) => m.metadata.category !== 'posthog_pii');
  }
  // Any match blocks — except publish_handoff, critical only.
  const blocking =
    toolName === 'publish_handoff'
      ? publishBlockingMatch(matches)
      : matches[0] ?? null;

  recordExternalScan(
    phase,
    tool,
    matches.map(toReportViolation),
    blocking ? 'blocked' : 'warned',
  );
  if (!blocking) return undefined;

  const attempt = repeatTracker?.attempt(toolName, content) ?? 1;
  return repeatBlockReason(attempt, toolName, blockMessage(blocking));
}

/**
 * The pure gate decision for a single tool call. Reuses `wizardCanUseTool`
 * (deny → block) then the YARA content scan (match → block). Fail-closed: any
 * thrown error blocks.
 */
export async function evaluateToolCall(
  toolName: string,
  input: Record<string, unknown>,
  ctx: ToolGateContext = {},
  llmProvider?: LLMProvider,
): Promise<GateDecision> {
  try {
    if (ctx.readOnly && !READ_ONLY_PI_TOOLS.has(toolName)) {
      return {
        block: true,
        reason: `Tool ${toolName} is disabled for read-only runs.`,
      };
    }
    const policy = toClaudePolicyCall(toolName, input);
    const decision = wizardCanUseTool(policy.name, policy.input, {
      disallowedTools: ctx.disallowedTools,
      wizardAskPending: ctx.getWizardAskPending?.() ?? false,
      workingDirectory: ctx.workingDirectory,
    });
    if (decision.behavior === 'deny') {
      return { block: true, reason: decision.message };
    }

    const yaraReason = await preExecutionYaraBlock(
      toolName,
      input,
      llmProvider,
      ctx.repeatTracker,
    );
    if (yaraReason) return { block: true, reason: yaraReason };

    if (toolName === 'write') {
      const shrinkReason = await overwriteShrinkBlock(
        input,
        ctx.workingDirectory,
      );
      if (shrinkReason) return { block: true, reason: shrinkReason };
    }

    return { block: false };
  } catch (err) {
    logToFile('[pi-security] gate error — failing closed:', err);
    // A publish_handoff the gate can't clear leaves the run with no report at
    // all, so end it visibly instead of letting the agent reword and retry.
    return {
      block: true,
      reason: 'Security check failed; tool blocked (fail-closed).',
      terminate: toolName === 'publish_handoff',
    };
  }
}

/** pi result tool names whose OUTPUT gets scanned for 'input'-context rules. */
function isPostScanTool(toolName: string): boolean {
  return toolName === 'read' || toolName === 'bash';
}

/** Mutable state the backend reads after the run to classify the outcome. */
export interface SecurityState {
  criticalViolation: boolean;
  blockedCount: number;
  toolCalls: number;
}

/** Options for {@link createSecurityExtension}. The root is required, so no run loses the rm allowance or the shrink guard by omission. */
export type SecurityExtensionOptions = ToolGateContext & {
  workingDirectory: string;
};

declare const subagentGate: unique symbol;

/** A gate with no project root, so it never allows rm. Only `subagentFactory` makes one, so a subagent can't be handed the parent's. */
export type SubagentSecurityFactory = ((pi: PiExtensionApiLike) => void) & {
  readonly [subagentGate]: true;
};

/**
 * Build the pi security extension + the shared state the backend inspects.
 * Install `factory` via `extensionFactories`. Give subagent sessions
 * `subagentFactory`: the same fence and state, with no project root, so no rm.
 */
export function createSecurityExtension(ctx: SecurityExtensionOptions): {
  factory: (pi: PiExtensionApiLike) => void;
  subagentFactory: SubagentSecurityFactory;
  state: SecurityState;
} {
  const state: SecurityState = {
    criticalViolation: false,
    blockedCount: 0,
    toolCalls: 0,
  };

  // One triage provider per extension. Undefined (no gateway auth) means
  // triage is skipped and every flagged match is acted on — fail closed.
  const llmProvider = ctx.triageProvider;

  // One tracker per extension = per (sub)agent session, so an identical
  // payload retried after a block gets the escalating reason.
  const gateCtx: ToolGateContext = {
    ...ctx,
    repeatTracker: ctx.repeatTracker ?? createRepeatBlockTracker(),
  };

  const install = (pi: PiExtensionApiLike, gate: ToolGateContext): void => {
    pi.on('tool_call', async (event) => {
      // A latched post-scan violation blocks everything that follows.
      if (state.criticalViolation) {
        return {
          block: true,
          reason: 'Run terminated by a security violation.',
        };
      }
      state.toolCalls += 1;
      if (state.toolCalls > MAX_TOOL_CALLS) {
        return {
          block: true,
          reason: `Stopped: exceeded ${MAX_TOOL_CALLS} tool calls (runaway guard).`,
        };
      }
      const decision = await evaluateToolCall(
        event.toolName,
        event.input ?? {},
        gate,
        llmProvider,
      );
      if (decision.block) {
        state.blockedCount += 1;
        if (decision.terminate) state.criticalViolation = true;
        logToFile(`[pi-security] BLOCK ${event.toolName}: ${decision.reason}`);
        return { block: true, reason: decision.reason };
      }
      // Keep .env files out of directory greps; a glob that selects one is refused above.
      if (event.toolName === 'grep' && event.input && !event.input.glob)
        event.input.glob = '!.env*';
      return {};
    });

    pi.on('tool_result', async (event) => {
      if (!isPostScanTool(event.toolName)) return {};
      const text = (event.content ?? [])
        .map((c) => (c && c.type === 'text' ? c.text : ''))
        .join('\n');
      if (!text) return {};
      try {
        // 'input'-context rules (prompt injection in read content), with
        // triage — same policy as the anthropic PostToolUse Read hook.
        const matches = await scanAndTriage(text, 'input', llmProvider);
        const verdict = scanVerdict(matches);
        // Count the scan even when clean, like the anthropic hooks do.
        recordExternalScan(
          'PostToolUse',
          event.toolName === 'read' ? 'Read' : 'Bash',
          matches.map(toReportViolation),
          verdict?.action ?? 'warned',
        );
        if (!verdict) return {};
        if (verdict.terminal) {
          state.criticalViolation = true;
          logToFile(
            `[pi-security] POST-SCAN VIOLATION ${event.toolName}: ${verdict.match.rule}`,
          );
        } else {
          logToFile(
            `[pi-security] POST-SCAN WARNING ${event.toolName}: ${
              verdict.match.rule
            } (severity: ${verdict.match.metadata.severity ?? 'unknown'})`,
          );
        }
      } catch (err) {
        // Fail closed: a scanner error on output latches a violation.
        state.criticalViolation = true;
        logToFile('[pi-security] post-scan error — failing closed:', err);
      }
      return {};
    });
  };

  const subagentCtx: ToolGateContext = {
    ...gateCtx,
    workingDirectory: undefined,
  };
  return {
    factory: (pi) => install(pi, gateCtx),
    subagentFactory: ((pi: PiExtensionApiLike) =>
      install(pi, subagentCtx)) as SubagentSecurityFactory,
    state,
  };
}

/**
 * Minimal structural type for pi's ExtensionAPI — just the `on` overloads we
 * use. Kept local so this module has no value import from the pi SDK (so the
 * CommonJS unit tests can load it directly). Handlers may return promises —
 * pi's real ExtensionHandler is `(event, ctx) => Promise<R | void> | R | void`.
 */
export interface PiExtensionApiLike {
  on(
    event: 'tool_call',
    handler: (event: {
      toolName: string;
      input?: Record<string, unknown>;
    }) =>
      | { block?: boolean; reason?: string }
      | Promise<{ block?: boolean; reason?: string }>,
  ): void;
  on(
    event: 'tool_result',
    handler: (event: {
      toolName: string;
      content?: Array<{ type: string; text?: string }>;
      isError?: boolean;
    }) => Record<string, never> | Promise<Record<string, never>>,
  ): void;
}

